sub(p, '''export async function getIssue(''', '''/**
 * Moves an issue to another project of the same workspace (ADR 0011). The
 * actor needs `issue:update` on the issue and `issue:create` in the target,
 * and the target's per-project quota applies as it does to a new issue; all
 * of that is settled before anything is written. The issue takes the next
 * number of the target project and its old number is retired. Only
 * `issue.moved` is published — the audit entry and the search entry follow
 * from it. Moving within the same project does nothing.
 */
export async function moveIssueToProject(
  actor: Actor,
  input: MoveIssueToProjectInput,
): Promise<Issue> {
  assertOrgScope(actor, input.orgId);

  const before = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  assertCan(actor, "issue:update", issueResource(before));
  assertNotArchived("Issue", before.id, before);

  if (before.projectId === input.toProjectId) return before;

  const target = requireFound(
    await projectRepo.findProjectById(input.orgId, input.toProjectId),
    "Project",
    input.toProjectId,
  );
  assertNotArchived("Project", target.id, target);
  assertCan(actor, "issue:create", projectResource(target));

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );
  const used = await issueRepo.countIssues(input.orgId, target.id);
  if (wouldExceedLimit(org.plan, "issuesPerProject", used)) {
    throw new Error(
      `Plan ${org.plan} allows no more issues in project ${target.key}`,
    );
  }

  const move = await issueRepo.moveIssueToProject(
    input.orgId,
    input.issueId,
    target.id,
  );

  await emit("issue.moved", {
    ...actorEnvelope(actor),
    issueId: input.issueId,
    fromProjectId: move.fromProjectId,
    toProjectId: target.id,
    fromNumber: move.fromNumber,
    toNumber: move.toNumber,
  });

  return requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
}

