import type { Tenant } from "../server/_support/fixtures";

let cleanup: () => void;
let t: Tenant;
beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  t = await createTenant("mv");
});
afterAll(() => cleanup());

describe("move", () => {
  it("works", async () => {
    const offA = registerActivityListeners();
    const offS = registerSearchListeners();
    const other = await projectRepo.insertProject({
