      visibility: "org", leadId: t.userIds.owner, color: "#000000", targetDate: null,
    });
    const events: unknown[] = [];
    const off = subscribe("issue.moved", (p) => { events.push(p); });
    const created: string[] = [];
    const offC = subscribe("issue.created", (p) => { created.push(p.issueId); });

    const a = await issueService.createIssue(t.actors.member, issueInput(t.org.id, t.project.id, { title: "Alpha issue" }));
    const b = await issueService.createIssue(t.actors.member, issueInput(t.org.id, t.project.id, { title: "Bravo issue" }));
    expect([a.number, b.number]).toEqual([1, 2]);

    const moved = await issueService.moveIssueToProject(t.actors.member, { orgId: t.org.id, issueId: b.id, toProjectId: other.id });
