    const back = await issueService.moveIssueToProject(t.actors.member, { orgId: t.org.id, issueId: b.id, toProjectId: t.project.id });
    expect(back.number).toBe(4);
    // other project retired 1
    const d = await issueService.createIssue(t.actors.member, issueInput(t.org.id, other.id, { title: "Delta issue" }));
    expect(d.number).toBe(2);

    // same project no-op
    events.length = 0;
    const same = await issueService.moveIssueToProject(t.actors.member, { orgId: t.org.id, issueId: b.id, toProjectId: t.project.id });
    expect(same.number).toBe(4);
    expect(events).toHaveLength(0);

    // permission
    await expect(issueService.moveIssueToProject(t.actors.viewer, { orgId: t.org.id, issueId: a.id, toProjectId: other.id })).rejects.toBeInstanceOf(PermissionDeniedError);
    expect((await issueRepo.findIssueById(t.org.id, a.id))?.projectId).toBe(t.project.id);

    // audit
    const page = await listActivity(t.actors.member, { orgId: t.org.id, action: ["issue.moved"], limit: 25, cursor: null });
    expect(page.items.length).toBe(2);
    console.log(JSON.stringify(page.items.map(i => [i.projectId, i.metadata, i.summary])));

    // search
    const inOther = await search(t.actors.member, { orgId: t.org.id, q: "Delta", kinds: [], limit: 25, cursor: null } as never);
    expect(inOther.total).toBe(1);
    const bravo = await search(t.actors.member, { orgId: t.org.id, q: "Bravo", kinds: [], limit: 25, cursor: null, projectId: other.id } as never);
    expect(bravo.total).toBe(0);
    const bravo2 = await search(t.actors.member, { orgId: t.org.id, q: "Bravo", kinds: [], limit: 25, cursor: null, projectId: t.project.id } as never);
    expect(bravo2.total).toBe(1);
    off(); offC(); offA(); offS();
  });
});
EOF
