/**
 * Moving an issue to another project (ADR 0011): numbering, permissions,
 * quota, the single `issue.moved` event, and the audit and search entries.
 */
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { subscribe } from "@/lib/event-bus";
import { PermissionDeniedError } from "@/lib/permissions";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import { listActivity, registerActivityListeners } from "@/server/services/activity-service";
import * as issueService from "@/server/services/issue-service";
import { registerSearchListeners, search } from "@/server/services/search-service";
import { toIsoTimestamp } from "@/types/common";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { TaskflowEventType, Unsubscribe } from "@/types/event";

let cleanup: () => void;
let tenant: Tenant;
const detachers: Unsubscribe[] = [];

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("movesvc");
  detachers.push(registerActivityListeners(), registerSearchListeners());
});

afterEach(() => {
  // Listeners registered in beforeAll stay; per-test captures are detached by the tests.
});

afterAll(() => {
  while (detachers.length > 0) detachers.pop()?.();
  cleanup();
});

let projectSeq = 0;

async function newProject() {
  projectSeq += 1;
  return projectRepo.insertProject({
    orgId: tenant.org.id,
    name: `Target ${projectSeq}`,
    slug: `target-${projectSeq}`,
    key: `TG${projectSeq}`,
    description: null,
    visibility: "org",
    leadId: tenant.userIds.owner,
    color: "#6366f1",
    targetDate: null,
  });
}

async function newIssue(projectId: Tenant["project"]["id"], title: string) {
  return issueService.createIssue(
    tenant.actors.member,
    issueInput(tenant.org.id, projectId, { title }),
  );
}

function capture(type: TaskflowEventType): unknown[] {
  const seen: unknown[] = [];
  const off = subscribe(type, (payload) => {
    seen.push(payload);
  });
  detachers.push(off);
  return seen;
}

describe("issueService.moveIssueToProject", () => {
  it("gives the issue the target's next number and retires the old one", async () => {
    const target = await newProject();
    await newIssue(target.id, "Already in target");
    const issue = await newIssue(tenant.project.id, "Wrongly filed");

    const moved = await issueService.moveIssueToProject(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      toProjectId: target.id,
    });

    expect(moved.projectId).toBe(target.id);
    expect(moved.number).toBe(2);
    expect(moved.title).toBe(issue.title);
    expect(moved.status).toBe(issue.status);

    // The source never hands the moved issue's number out again.
    const next = await issueRepo.nextIssueNumber(tenant.org.id, tenant.project.id);
    expect(next).toBeGreaterThan(issue.number);

    // ...not even when the issue comes back.
    const back = await issueService.moveIssueToProject(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      toProjectId: tenant.project.id,
    });
    expect(back.number).toBe(next);
    const targetNext = await issueRepo.nextIssueNumber(tenant.org.id, target.id);
    expect(targetNext).toBe(3);
  });

  it("publishes exactly one issue.moved, on behalf of the actor", async () => {
    const target = await newProject();
    const issue = await newIssue(tenant.project.id, "Announce me");
    const moved = capture("issue.moved");
    const others = [
      capture("issue.created"),
      capture("issue.updated"),
      capture("issue.archived"),
    ];

    await issueService.moveIssueToProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      issueId: issue.id,
      toProjectId: target.id,
    });

    expect(moved).toHaveLength(1);
    expect(moved[0]).toMatchObject({
      orgId: tenant.org.id,
      actorId: tenant.userIds.admin,
      issueId: issue.id,
      fromProjectId: tenant.project.id,
      toProjectId: target.id,
      fromNumber: issue.number,
      toNumber: 1,
    });
    expect(others.every((seen) => seen.length === 0)).toBe(true);
  });

  it("changes nothing and publishes nothing within the same project", async () => {
    const issue = await newIssue(tenant.project.id, "Stay put");
    const moved = capture("issue.moved");

    const result = await issueService.moveIssueToProject(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      toProjectId: tenant.project.id,
    });

    expect(result).toEqual(issue);
    expect(moved).toHaveLength(0);
  });

  it("needs issue:create in the target and leaves the issue alone when refused", async () => {
    const target = await newProject();
    const issue = await issueService.createIssue(
      tenant.actors.viewer,
      issueInput(tenant.org.id, tenant.project.id),
    ).catch(() => null);
    expect(issue).toBeNull();

    // A viewer authored nothing here; give them an issue they may edit by
    // assignment, which grants issue:update but not issue:create.
    const assigned = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Assigned to the viewer",
        assigneeId: tenant.userIds.viewer,
      }),
    );
    const moved = capture("issue.moved");

    await expect(
      issueService.moveIssueToProject(tenant.actors.viewer, {
        orgId: tenant.org.id,
        issueId: assigned.id,
        toProjectId: target.id,
      }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    expect(await issueRepo.findIssueById(tenant.org.id, assigned.id)).toEqual(assigned);
    expect(moved).toHaveLength(0);
  });

  it("applies the target project's issue quota and changes nothing when refused", async () => {
    const free = await createTenant("movequota", "free");
    const target = await projectRepo.insertProject({
      orgId: free.org.id,
      name: "Full",
      slug: "full",
      key: "FULL",
      description: null,
      visibility: "org",
      leadId: free.userIds.owner,
      color: "#6366f1",
      targetDate: toIsoTimestamp(new Date()) as never,
    });
    for (let number = 1; number <= 100; number += 1) {
      await issueRepo.insertIssue(
        issueInput(free.org.id, target.id, { title: `Filler ${number}` }),
        free.userIds.member,
        number,
      );
    }
    const issue = await issueService.createIssue(
      free.actors.member,
      issueInput(free.org.id, free.project.id, { title: "Does not fit" }),
    );

    await expect(
      issueService.moveIssueToProject(free.actors.member, {
        orgId: free.org.id,
        issueId: issue.id,
        toProjectId: target.id,
      }),
    ).rejects.toThrow(/allows no more issues/);

    expect(await issueRepo.findIssueById(free.org.id, issue.id)).toEqual(issue);
  });

  it("refuses a target project of another workspace", async () => {
    const other = await createTenant("moveother");
    const issue = await newIssue(tenant.project.id, "Stay in your org");

    await expect(
      issueService.moveIssueToProject(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: issue.id,
        toProjectId: other.project.id,
      }),
    ).rejects.toThrow(/not found/);

    expect((await issueRepo.findIssueById(tenant.org.id, issue.id))?.projectId).toBe(
      tenant.project.id,
    );
  });

  it("records the move once under the target project and re-files the search entry", async () => {
    const target = await newProject();
    const issue = await newIssue(tenant.project.id, "Zebrafish migration");

    await issueService.moveIssueToProject(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      toProjectId: target.id,
    });

    const audit = await listActivity(tenant.actors.member, {
      orgId: tenant.org.id,
      action: ["issue.moved"],
      subjectKind: "issue",
      projectId: target.id,
      limit: 25,
      cursor: null,
    });
    expect(audit.items).toHaveLength(1);
    expect(audit.items[0]).toMatchObject({
      subjectKind: "issue",
      subjectId: issue.id,
      projectId: target.id,
      metadata: {
        fromProjectId: tenant.project.id,
        toProjectId: target.id,
        fromNumber: issue.number,
        toNumber: 1,
      },
    });

    // The entry written when the issue was created keeps its project.
    const created = await listActivity(tenant.actors.member, {
      orgId: tenant.org.id,
      action: ["issue.created"],
      projectId: tenant.project.id,
      limit: 100,
      cursor: null,
    });
    expect(created.items.some((event) => event.subjectId === issue.id)).toBe(true);

    const query = { orgId: tenant.org.id, q: "Zebrafish", kinds: [], limit: 25, cursor: null };
    expect((await search(tenant.actors.member, { ...query, projectId: target.id })).total).toBe(1);
    expect(
      (await search(tenant.actors.member, { ...query, projectId: tenant.project.id })).total,
    ).toBe(0);
  });
});
EOF
